"""Emit the mechanical C++20 aggregate decomposition table for state inspection."""
from pathlib import Path

output = Path(__file__).resolve().parents[1] / "port/src/online/state_aggregate.hpp"
lines = [
    "// Generated by scripts/generate-state-aggregate.py; do not edit by hand.",
    "#pragma once",
    "#include <type_traits>",
    "#include <utility>",
    "namespace phantomcrash::online {",
    "namespace state_detail {",
    "struct Any { template <class T> operator T() const; };",
    "template <class T, std::size_t... I>",
    "constexpr bool accepts(std::index_sequence<I...>) {",
    "  return requires { T{(static_cast<void>(I), Any{})...}; };",
    "}",
    "template <class T, std::size_t N = 0> constexpr std::size_t count() {",
    "  static_assert(N <= 128, \"State record exceeds decomposition table\");",
    "  if constexpr (accepts<T>(std::make_index_sequence<N + 1>{})) {",
    "    return count<T, N + 1>();",
    "  } else { return N; }",
    "}",
    "} // namespace state_detail",
    "template <class T, class F> void visit_state_aggregate(const T &value, F &&visit) {",
    "  static_assert(std::is_aggregate_v<T> && !std::is_array_v<T>);",
    "  constexpr auto count = state_detail::count<T>();",
    "  static_assert(count > 0 || std::is_empty_v<T>, \"State aggregate cannot be decomposed\");",
    "  if constexpr (count == 0) { visit(); }",
]
for count in range(1, 129):
    fields = ", ".join(f"f{i}" for i in range(count))
    lines.extend([
        f"  else if constexpr (count == {count}) {{",
        f"    const auto &[{fields}] = value;",
        f"    visit({fields});",
        "  }",
    ])
lines += ["}", "} // namespace phantomcrash::online", ""]
output.write_text("\n".join(lines), encoding="utf-8")
